// Excel 导出 - 基础导出示例
// 查询数据
var data = db.select("select id, username, email, create_time from sys_user where is_del = 0 limit 10")

// 定义表头映射
var headers = {
    "id": "ID",
    "username": "用户名",
    "email": "邮箱",
    "create_time": "创建时间"
}

// 导出为 Excel 并下载
excel.download(data, "用户导出", headers)
